/// <reference types="react" />
import type { Row } from 'react-table';
export interface UseSubRowsRowProps {
    hasSubRows?: boolean;
    subRowsOpen?: boolean;
    subRowsDisabled?: boolean;
}
export interface UseSubRowsInstanceProps {
    subRowsDepth: number;
    allSubRowsOpen: boolean;
    setOpenSubRows: React.Dispatch<React.SetStateAction<Record<string, boolean>>>;
    updateOpenSubRows: (update: string | boolean) => void;
}
export interface UseSubRowsState {
    openSubRows: Record<string, boolean>;
}
export interface UseSubRowsColumnInstanceProps {
    /** Defines the accessor for the sub rows data. Can either be a string or an accessor function. */
    subRowsAccessor?: ((row: Row, index: number) => any[]) | string;
    /** Function defining if the sub rows of the current row can be opened or not */
    disableSubRows?: (row: Row) => boolean;
}
